(function () {
  'use strict';
  window.QUESTION_BANK = Object.assign(window.QUESTION_BANK || {}, {"grammar-sentence-types":{"title":"Sentence Types","topic":"Grammar & Usage","questions":[{"id":"grammar-sentence-types-q0001","version":4,"contentHash":"sha256:288fe68e45770443657e4d8d3e0043aeb1b0d8dff0d9e2e27d6e85218bb7db73","question":"Which sentence is a command even though it ends with a period?","choices":["The library closes at five.","Please return the books by Friday.","What time does the library close?","What a quiet library this is!"],"correct":1,"studyAid":{"definition":"An imperative sentence gives a command, makes a request, or gives an instruction. It usually ends with a period or an exclamation point.","example":"Eat your vegetables. (Command), Please wait here. (Request), Stop running! (Strong command)","strategyClue":"Look for the sentence that directs someone to perform an action. Ask yourself: 'Does this sentence tell me to do something, tell me a fact, ask something, or show strong feeling?'","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Please return the books by Friday. A command, or imperative sentence, tells someone to do something. Even though it ends with a period, the word 'Please' indicates a request or command directed at the listener.","incorrect":[{"choice":"The library closes at five.","category":"declarative sentence","reason":"This is a statement of fact about the library's schedule, not a request or command for someone to take action."},"",{"choice":"What time does the library close?","category":"interrogative sentence","reason":"This sentence ends with a question mark and asks for information, making it a question rather than a command."},{"choice":"What a quiet library this is!","category":"exclamatory sentence","reason":"This sentence ends with an exclamation point and expresses strong emotion, so it is an exclamation, not a command."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":1,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0002","version":4,"contentHash":"sha256:edb8ea0b82ffe1c3ce6929aa759e536d540d060ccf733eb3ed67e8031de8440c","question":"Which sentence is exclamatory because it shows strong feeling?","choices":["The storm knocked down two branches.","Did the storm knock down two branches?","What a powerful storm that was!","Bring the branches to the curb."],"correct":2,"studyAid":{"definition":"An exclamatory sentence makes a strong statement or shows intense emotion like excitement, shock, or surprise. It always ends with an exclamation point (!).","example":"Correct: I won the race! / How cold it is! | Incorrect: I won the race. / How cold is it?","strategyClue":"Read each sentence out loud with a very excited voice. The one that feels like a powerful shout or a big reaction to a surprise is likely your exclamatory sentence.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: What a powerful storm that was!. An exclamatory sentence expresses strong emotion or excitement and must end with an exclamation mark.","incorrect":[{"choice":"The storm knocked down two branches.","category":"declarative sentence","reason":"This is a statement of fact, which is a declarative sentence. It ends with a period, not an exclamation mark, and does not show strong feeling."},{"choice":"Did the storm knock down two branches?","category":"interrogative sentence","reason":"This sentence ends with a question mark because it is asking for information. It is an interrogative sentence, not an exclamatory one."},"",{"choice":"Bring the branches to the curb.","category":"imperative sentence","reason":"This is a command or request, which is an imperative sentence. Even though it might end with an exclamation mark in some cases, its primary purpose is to give an instruction, not express strong emotion."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":2,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0003","version":4,"contentHash":"sha256:9d568f44b028c13eb6d5488c6023e401a878f3f56c707b4843da4bdd68c1dd69","question":"Which sentence is interrogative?","choices":["Tell me whether the bus is late.","Is the bus late again?","The bus is late again.","What a late bus!"],"correct":1,"studyAid":{"definition":"An interrogative sentence asks a direct question and almost always ends with a question mark.","example":"Where is my hat? (Interrogative) vs. Put on your hat. (Imperative)","strategyClue":"Look at the end punctuation of each sentence. A sentence that asks for an answer and ends with a question mark is the one you are looking for.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Is the bus late again?. An interrogative sentence is a question that asks for information and typically ends with a question mark.","incorrect":[{"choice":"Tell me whether the bus is late.","category":"imperative sentence","reason":"This is an imperative sentence because it gives a command or a request. Even though it talks about a question, the sentence itself is a direction, not an inquiry."},"",{"choice":"The bus is late again.","category":"declarative sentence","reason":"This is a declarative sentence because it makes a statement or expresses an opinion. It ends with a period, which is used for telling facts rather than asking questions."},{"choice":"What a late bus!","category":"exclamatory sentence","reason":"This is an exclamatory sentence because it expresses strong emotion. It ends with an exclamation point to show surprise or frustration."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":3,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0004","version":4,"contentHash":"sha256:ff78c87a23f7d85ad40fd8e16ae16b19e4e34c838b35e49ae299aea6b4828417","question":"Which sentence is declarative even though it contains the word question?","choices":["The question was difficult.","Did you answer the question?","Answer the question now.","What a strange question!"],"correct":0,"studyAid":{"definition":"A declarative sentence tells information, states a fact, or gives an opinion and always ends with a period.","example":"The dog is happy. (Declarative) vs. Is the dog happy? (Interrogative)","strategyClue":"Look at the end mark of each sentence first. A declarative sentence must end with a period, not a question mark or an exclamation point.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The question was difficult. This is a declarative sentence because it makes a statement and ends with a period, even though it uses the word 'question' to talk about a problem.","incorrect":["",{"choice":"Did you answer the question?","category":"interrogative sentence type","reason":"This is an interrogative sentence because it asks a direct question and ends with a question mark. Declarative sentences must state a fact."},{"choice":"Answer the question now.","category":"imperative sentence type","reason":"This is an imperative sentence because it gives a command. It is asking the listener to do something rather than simply stating information."},{"choice":"What a strange question!","category":"exclamatory sentence type","reason":"This is an exclamatory sentence because it expresses strong emotion and ends with an exclamation point."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":4,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0005","version":4,"contentHash":"sha256:3ee96cc0c4bdb60a541cc4411185e85d523a6270b0b51b46367366f1923ac7f7","question":"A student writes, \"Please explain how you solved the problem!\" What type of sentence is it?","choices":["declarative","interrogative","imperative","fragment"],"correct":2,"studyAid":{"definition":"An imperative sentence gives a command, makes a request, or gives instructions. The subject is usually an implied 'you'.","example":"Close the door. (Command) Please sit down. (Request) Follow these steps. (Instruction)","strategyClue":"Look at the main verb of the sentence. If the sentence is telling someone to perform an action, identify it as a directive rather than a question or a statement of fact.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: imperative. This sentence is a command or a polite request. Even though it ends with an exclamation point, the sentence is instructing someone to do something.","incorrect":[{"choice":"declarative","category":"sentence type confusion","reason":"A declarative sentence simply makes a statement or expresses a fact. This sentence is asking the reader to perform the action of explaining."},{"choice":"interrogative","category":"sentence type confusion","reason":"While it sounds like a request for information, it is written as a direct command to explain, rather than a question structure starting with words like 'who', 'what', or 'how' that requires a question mark."},"",{"choice":"fragment","category":"incomplete sentence structure","reason":"This is not a fragment because it contains a clear subject (the implied 'you') and a predicate ('explain how you solved the problem'). It is a complete thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":5,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0006","version":4,"contentHash":"sha256:ec5f7324ac052d9440da6c9ef1be0cf10962b17dbc83cfdcc15aa7f14efbb928","question":"Which revision turns the statement into a direct question?","choices":["The science fair begins on Monday.","Does the science fair begin on Monday?","The science fair begins on Monday!","Begin the science fair on Monday."],"correct":1,"studyAid":{"definition":"A direct question is a sentence that asks for information and always ends with a question mark.","example":"Statement: You are happy. Question: Are you happy? Statement: It is raining. Question: Is it raining?","strategyClue":"Check if the sentence is requesting information and ends with a question mark. If it tells, commands, or exclaims, it is not a question.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Does the science fair begin on Monday?. This sentence starts with an auxiliary verb and ends with a question mark, which is the standard structure for a direct question.","incorrect":[{"choice":"The science fair begins on Monday.","category":"declarative sentence","reason":"This is a statement of fact that ends with a period. It provides information rather than asking for it."},"",{"choice":"The science fair begins on Monday!","category":"exclamatory sentence","reason":"This sentence uses an exclamation point, which shows excitement or strong emotion instead of asking a question."},{"choice":"Begin the science fair on Monday.","category":"imperative sentence","reason":"This is a command or instruction. It tells someone to do something rather than asking for information."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"compare every choice against the full rule, not justhe first visible error","estimatedTimeSeconds":55,"reviewPriority":"high","sourceSet":"grammar-sentence-types","sequence":6,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0007","version":4,"contentHash":"sha256:07aff4c42dad2939893602e189da1be39b118662a3430f04662d70be12775630","question":"Which sentence asks indirectly, so it should end with a period?","choices":["Can you tell me where the office is?","Where is the office?","I wonder where the office is.","Is the office near the gym?"],"correct":2,"studyAid":{"definition":"A direct question asks for information directly and ends with a question mark, while an indirect question states that you are curious and ends with a period.","example":"Direct: Where is my hat? Indirect: I wonder where my hat is.","strategyClue":"Look at the beginning of the sentence; if it starts with words like 'I wonder,' 'I want to know,' or 'Tell me,' it is expressing curiosity as a statement and needs a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: I wonder where the office is. This sentence is an indirect question, which acts as a statement of curiosity rather than a direct request for information, so it requires a period instead of a question mark.","incorrect":[{"choice":"Can you tell me where the office is?","category":"direct question structure","reason":"This sentence uses a modal verb 'can' to ask a direct question, which requires a question mark at the end."},{"choice":"Where is the office?","category":"direct question","reason":"This is a standard direct inquiry starting with a question word. Because it directly asks for information, it must end with a question mark."},"",{"choice":"Is the office near the gym?","category":"direct question","reason":"When you put the verb 'is' at the start of a sentence to ask for a 'yes' or 'no' answer, you have created a direct question that needs a question mark."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":7,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0008","version":4,"contentHash":"sha256:6ea24adbbad05d1b9d3ad53decdf51a9abbfea5328f68d8eb098ae6cbd6ef33a","question":"Which choice is a declarative sentence with correct punctuation?","choices":["The trail was muddy after the rain?","The trail was muddy after the rain.","How muddy the trail was.","Walk around the muddy trail?"],"correct":1,"studyAid":{"definition":"A declarative sentence tells information and always ends with a period. It is the most common type of sentence used in writing.","example":"Declarative: The dog barked. / Not declarative: Did the dog bark? / Run to the dog!","strategyClue":"Check the end of the sentence for a period and ask yourself if the sentence is stating a fact or asking a question; if it's just stating a fact, it must have a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The trail was muddy after the rain. A declarative sentence makes a statement or expresses an opinion and must end with a period. This sentence provides information and uses the correct terminal punctuation.","incorrect":[{"choice":"The trail was muddy after the rain?","category":"incorrect terminal punctuation","reason":"A question mark is used only for interrogative sentences that ask a question. Since this sentence is a statement, it requires a period instead."},"",{"choice":"How muddy the trail was.","category":"exclamatory sentence structure","reason":"This sentence is structured as an exclamation, often requiring an exclamation point, rather than a neutral declarative statement."},{"choice":"Walk around the muddy trail?","category":"imperative and punctuation mismatch","reason":"This choice uses the structure of an imperative command but adds a question mark, which does not create a standard declarative sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":8,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0009","version":4,"contentHash":"sha256:a34ff77290b7edcd35c2fd83a44fed0365e7c52f797a30d4d5f93285496e1fcd","question":"Which sentence is a command with an understood subject \"you\"?","choices":["The pencils are on the desk.","Did the pencils fall?","Place the pencils on the desk.","What sharp pencils those are!"],"correct":2,"studyAid":{"definition":"An imperative sentence gives a command or makes a request. The subject 'you' is not written in the sentence but is understood to be the listener.","example":"Close the door. (You close the door.) / Pick up your toys. (You pick up your toys.)","strategyClue":"Look for a sentence that starts with a verb and tells someone to perform an action. If you can add 'You' to the very beginning of the sentence and it still makes sense, it is likely a command.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Place the pencils on the desk. This is an imperative sentence because it gives a direct order and the subject 'you' is understood to be the person being addressed.","incorrect":[{"choice":"The pencils are on the desk.","category":"declarative sentence","reason":"This sentence makes a statement about where the pencils are, but it does not give an order. It has a visible subject, 'The pencils'."},{"choice":"Did the pencils fall?","category":"interrogative sentence","reason":"This is a question used to find out information. Commands do not usually ask questions; they tell someone to perform an action."},"",{"choice":"What sharp pencils those are!","category":"exclamatory sentence","reason":"This sentence expresses strong emotion or surprise. Because it contains a clear subject ('those') and a verb ('are'), it is not a command."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":9,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0010","version":4,"contentHash":"sha256:c8c8ff79283455fdff24eafe540919e8eb24cd2ac3586038e0f67e05b68c659e","question":"Which sentence is NOT interrogative?","choices":["Have you packed your lunch?","When does practice start?","I asked when practice starts.","Will practice start soon?"],"correct":2,"studyAid":{"definition":"An interrogative sentence asks a direct question and usually ends with a question mark. A declarative sentence makes a statement and ends with a period.","example":"Question: Where is my bag? Statement: I know where my bag is.","strategyClue":"Look at the end punctuation and think about whether the sentence is requesting an answer or simply sharing information.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: I asked when practice starts. This sentence is a statement (declarative) because it describes an action the speaker performed, rather than asking a direct question.","incorrect":[{"choice":"Have you packed your lunch?","category":"interrogative sentence","reason":"This sentence asks for information and ends with a question mark, which makes it interrogative."},{"choice":"When does practice start?","category":"interrogative sentence","reason":"This sentence begins with a 'when' question word and seeks specific information, making it interrogative."},"",{"choice":"Will practice start soon?","category":"interrogative sentence","reason":"This sentence asks a question that requires a 'yes' or 'no' answer, which defines it as an interrogative sentence."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"grammar-sentence-types","sequence":10,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0011","version":4,"contentHash":"sha256:7660731d1b9f1e1e0cfbe524c82bd8112ffd3d1424a87062f40db6cde181750d","question":"Which sentence type best fits: \"What a careful reader you are!\"","choices":["declarative","interrogative","imperative","exclamatory"],"correct":3,"studyAid":{"definition":"An exclamatory sentence is used to express strong feelings like surprise, joy, or excitement and always ends with an exclamation point.","example":"I am so happy! (Exclamatory) vs. I am happy. (Declarative)","strategyClue":"Look closely at the final punctuation mark and decide if the sentence is making a request, asking for information, or expressing a big, strong emotion.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: exclamatory. This sentence expresses strong emotion and ends with an exclamation point, which is the defining mark of an exclamatory sentence.","incorrect":[{"choice":"declarative","category":"sentence type confusion","reason":"A declarative sentence simply makes a statement and ends with a period. This sentence is too excited to be a simple statement."},{"choice":"interrogative","category":"sentence type confusion","reason":"An interrogative sentence asks a question and ends with a question mark. Even though this starts with the word 'What,' it is not asking for information."},{"choice":"imperative","category":"sentence type confusion","reason":"An imperative sentence gives a command or request. This sentence is meant to share excitement or praise, not tell someone to do something."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":11,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0012","version":4,"contentHash":"sha256:7e7482d6a8cad54a037963f2c15d6afa3b6f832ec99094203586ab85d2f15496","question":"Which sentence uses punctuation that matches its purpose?","choices":["Did you find my notebook.","Please lower your voice?","The class voted for a new mascot.","What a long assignment this is."],"correct":2,"studyAid":{"definition":"Sentences end with specific marks: a period for statements/commands, a question mark for questions, and an exclamation point for strong feelings.","example":"I like cake. (statement) Did you sleep well? (question) Look out! (strong feeling)","strategyClue":"Read the sentence out loud and ask yourself: 'Am I asking something?', 'Am I shouting or feeling excited?', or 'Am I just telling someone a fact?'","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The class voted for a new mascot. This sentence is a statement of fact, so it correctly uses a period at the end.","incorrect":[{"choice":"Did you find my notebook.","category":"incorrect end punctuation","reason":"This is a question, so it needs a question mark at the end instead of a period."},{"choice":"Please lower your voice?","category":"incorrect end punctuation","reason":"This is a command or request, so it should end with a period rather than a question mark."},"",{"choice":"What a long assignment this is.","category":"missing exclamation point","reason":"This sentence expresses strong emotion or surprise, so it should end with an exclamation point instead of a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":12,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0013","version":5,"contentHash":"sha256:3374d444e7cca58bfaa3c03359b192c298188ead9e14cd0e36d792a6a2656743","question":"Which pair correctly matches sentence to type?","choices":["\"The bell rang.\" - interrogative","\"Ring the bell.\" - imperative","\"Did the bell ring?\" - declarative","\"What a loud bell.\" - exclamatory"],"correct":1,"studyAid":{"definition":"Sentences are categorized by their purpose: Declarative (statements), Interrogative (questions), Imperative (commands), and Exclamatory (strong emotion).","example":"Declarative: The dog barks. Interrogative: Who is there? Imperative: Sit down. Exclamatory: How exciting!","strategyClue":"Look at the punctuation first, then ask yourself: 'Is this sentence asking a question, shouting with excitement, telling someone to do something, or just stating a fact?'","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: \"Ring the bell.\" - imperative. An imperative sentence gives a command or makes a request, and it often has an implied subject of 'you'.","incorrect":[{"choice":"\"The bell rang.\" - interrogative","category":"incorrect sentence type","reason":"This sentence is a statement of fact, making it declarative. An interrogative sentence must ask a question."},"",{"choice":"\"Did the bell ring?\" - declarative","category":"incorrect sentence type","reason":"This sentence ends with a question mark and asks for information, which makes it an interrogative sentence, not a declarative one."},{"choice":"\"What a loud bell.\" - exclamatory","category":"misidentified sentence type","reason":"While this correctly labels the sentence as exclamatory, the prompt asks for the pair that matches the sentence to its type, and this choice is often confused with declarative if the end punctuation is not carefully checked."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":13,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0014","version":4,"contentHash":"sha256:6a1287e6272a0836b60373725fcd333637ea1fed25ac53f1b40d1a7ac84bfa14","question":"Which sentence is a statement, not a command?","choices":["Walk to the front office.","You should walk to the front office.","Please walk to the front office.","Do not walk to the front office."],"correct":1,"studyAid":{"definition":"A statement (declarative sentence) tells the reader information, while a command (imperative sentence) tells the reader to do something.","example":"Statement: You like pizza. Command: Eat the pizza.","strategyClue":"Ask yourself: 'Is this sentence telling someone to do an action, or is it just describing a situation?' Look for the subject of the sentence to see if it is explaining who is doing the action.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: You should walk to the front office. A statement (declarative sentence) shares information or a thought. This sentence tells us what someone should do rather than giving a direct order.","incorrect":[{"choice":"Walk to the front office.","category":"imperative sentence","reason":"This is a command because it tells someone exactly what to do. Commands often start with an action verb and have an 'invisible' subject 'you'."},"",{"choice":"Please walk to the front office.","category":"polite command","reason":"Even though it uses the word 'please', this is still a command asking someone to perform an action. Statements report facts or ideas instead of making requests."},{"choice":"Do not walk to the front office.","category":"negative command","reason":"This is a negative command. It gives a direct instruction about what NOT to do, which makes it a command rather than a simple statement."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"spot the exception, then explain why the other choices follow the rule","estimatedTimeSeconds":35,"reviewPriority":"high","sourceSet":"grammar-sentence-types","sequence":14,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0015","version":4,"contentHash":"sha256:6264ee7696299d53a7bbc7e0437badbf3f7ace45003723c6b2c08b6e9890ec08","question":"Which sentence should end with an exclamation point because it is urgent?","choices":["Please pass the notebook","Watch out for the falling branch","The branch fell yesterday","Did the branch fall yesterday"],"correct":1,"studyAid":{"definition":"An exclamation point (!) is used at the end of sentences that express strong feelings, excitement, or urgent commands.","example":"Stop that car! (Urgent command) I am so happy! (Strong emotion) That was a close call!","strategyClue":"Read each sentence out loud and imagine the tone of voice. If the sentence sounds like someone shouting for safety or expressing high intensity, it needs an exclamation point.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Watch out for the falling branch. This sentence is an imperative command that expresses strong emotion or an urgent warning, which requires an exclamation point.","incorrect":[{"choice":"Please pass the notebook","category":"polite request punctuation","reason":"This is a polite request, not an urgent command. It should end with a period."},"",{"choice":"The branch fell yesterday","category":"statement of fact","reason":"This sentence is simply stating a fact about something that already happened, so it needs a period."},{"choice":"Did the branch fall yesterday","category":"interrogative sentence type","reason":"This is a question asking for information, which requires a question mark at the end."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":15,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0016","version":4,"contentHash":"sha256:3145dc5a4b75e2035b44fecea369d08c45b9315c2e3daad188c63895574ad19c","question":"Which sentence should end with a period?","choices":["How far is the museum","What a huge museum","The museum opens at noon","Open the museum door now"],"correct":2,"studyAid":{"definition":"A declarative sentence states a fact or idea and always ends with a period. Other sentences use different punctuation based on their purpose, such as asking questions or expressing excitement.","example":"Statement: The cat is soft. (Period) Question: Is the cat soft? (Question Mark) Excitement: What a soft cat! (Exclamation Point)","strategyClue":"Ask yourself if the sentence is telling you information, asking for info, or showing strong emotion. Only sentences that simply state a fact should have a period.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: The museum opens at noon. This sentence is a declarative sentence, which makes a statement or expresses a fact, so it must end with a period.","incorrect":[{"choice":"How far is the museum","category":"interrogative sentence","reason":"This is a question asking for information. Questions require a question mark at the end instead of a period."},{"choice":"What a huge museum","category":"exclamatory sentence","reason":"This sentence expresses strong emotion or surprise. Sentences like this need an exclamation point to show excitement."},"",{"choice":"Open the museum door now","category":"imperative sentence","reason":"While this is a command and usually ends with a period, it is often expressed with urgency. However, in this specific group, the declarative sentence is the standard statement of fact that strictly requires a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":16,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0017","version":4,"contentHash":"sha256:b8b5034c8d02091c768b1257dae10b15bde3f7a2ed68dd20b3d62645719c4434","question":"What type is this sentence after correct punctuation is added: \"Have you ever seen the Grand Canyon\"?","choices":["statement","command","question","exclamation"],"correct":2,"studyAid":{"definition":"A question (interrogative sentence) is used to ask for information and always ends with a question mark.","example":"Question: Did you eat lunch? Statement: I ate lunch. Command: Eat your lunch! Exclamation: I love lunch!","strategyClue":"Ask yourself: 'Is the speaker waiting for an answer, or are they just telling me something?' If the sentence is looking for a response, identify the punctuation needed to ask that.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: question. A sentence that asks for information and ends with a question mark is classified as an interrogative sentence, or a question.","incorrect":[{"choice":"statement","category":"declarative sentence error","reason":"A statement tells a fact or shares information and ends with a period. Because this sentence asks for information, it is not a statement."},{"choice":"command","category":"imperative sentence error","reason":"A command gives an instruction or a request. This sentence does not tell someone to do something; it asks if they have seen a place."},"",{"choice":"exclamation","category":"exclamatory sentence error","reason":"An exclamation expresses strong emotion or excitement and ends with an exclamation point. This sentence is seeking an answer, not showing intense feeling."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":17,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0018","version":4,"contentHash":"sha256:f04ffa2818abd05a6a494cc455f21eaf7eb4661e08e86ef1908606036ec944f7","question":"What type is this sentence after correct punctuation is added: \"Get out your math book\"?","choices":["statement","command","question","exclamation"],"correct":1,"studyAid":{"definition":"A command (imperative sentence) is a sentence that gives an order, makes a request, or gives instructions. The subject 'you' is usually hidden but understood.","example":"Close the door. (Command), Please sit down. (Command), I like cats. (Not a command)","strategyClue":"Ask yourself if the sentence is telling someone to do an action or if it is providing information. If you can add the word 'please' to the beginning of the sentence and it still makes sense, it is likely a command.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: command. A command, or imperative sentence, gives a request or order and typically has an implied subject of 'you'. This sentence tells someone to perform the action of getting out their book.","incorrect":[{"choice":"statement","category":"declarative sentence error","reason":"A statement provides information rather than telling someone to do something. Since this sentence gives a direct instruction, it is a command, not a statement."},"",{"choice":"question","category":"interrogative sentence error","reason":"A question is used to seek information and usually ends with a question mark. This sentence does not ask for information, so it is not a question."},{"choice":"exclamation","category":"exclamatory sentence error","reason":"An exclamation expresses strong emotion or surprise. While a command can sometimes be shouted, the primary function of this sentence is to give an instruction, making it a command."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":18,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0019","version":4,"contentHash":"sha256:d567649d1ae8671a5cfb84f159ac4b52515c40eb78294806387ecfddb371dade","question":"What type is this sentence after correct punctuation is added: \"Look out for that car\"?","choices":["statement","command","question","exclamation"],"correct":3,"studyAid":{"definition":"An exclamation sentence expresses strong feelings or a sudden shout and always ends with an exclamation mark (!).","example":"Watch out! (exclamation), I am tired. (statement), Did you see that? (question)","strategyClue":"Read the sentence out loud and pay attention to your tone. If you are shouting or expressing a burst of feeling, you need an exclamation mark.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: exclamation. This sentence expresses strong emotion or a sudden warning, so it ends with an exclamation point (!) to indicate that intensity.","incorrect":[{"choice":"statement","category":"declarative sentence type","reason":"A statement just shares information. This sentence is meant to grab attention and alert someone, which goes beyond a simple statement."},{"choice":"command","category":"imperative sentence type","reason":"While this sentence does tell someone what to do, its primary purpose is to express a sudden, urgent warning. Sentences meant to convey strong feeling are classified as exclamatory."},{"choice":"question","category":"interrogative sentence type","reason":"Questions are used to ask for information and end with a question mark. This sentence does not ask anything; it provides a warning."},""]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"sentence-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":19,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0020","version":4,"contentHash":"sha256:8e4da5959d97f8c14d0cdedad8b111d813abb3d00178bfd595e0ef004599ed60","question":"What type is this sentence after correct punctuation is added: \"Half of one dollar is fifty cents\"?","choices":["statement","command","question","exclamation"],"correct":0,"studyAid":{"definition":"A statement (declarative sentence) tells a fact or shares information and ends with a period. It is the most common type of sentence.","example":"Statement: The sky is blue. Command: Clean your room. Question: Where is my coat? Exclamation: That is amazing!","strategyClue":"Ask yourself if the sentence is giving you a fact, asking you something, telling you to act, or showing strong emotion. If it is just sharing information, it is a statement.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: statement. This sentence provides information or a fact, making it a declarative sentence. It ends with a period, which is the mark used for statements.","incorrect":["",{"choice":"command","category":"incorrect sentence type","reason":"A command (imperative sentence) tells someone to do something. Since this sentence simply states a fact about money, it is not a command."},{"choice":"question","category":"incorrect sentence type","reason":"A question (interrogative sentence) asks for information. Since this sentence is not asking for an answer, it cannot be a question."},{"choice":"exclamation","category":"incorrect sentence type","reason":"An exclamation (exclamatory sentence) expresses strong emotion or excitement and ends with an exclamation point. This sentence is a neutral fact, not an outburst."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":20,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0021","version":4,"contentHash":"sha256:b32e8ce53094cd178cfc3a20160ab3c2894abbd60a9a9683c5b8ed0032ed47ca","question":"Which sentence type can sometimes end with either a period or an exclamation point depending on force?","choices":["command","question","statement only","fragment"],"correct":0,"studyAid":{"definition":"Imperative sentences (commands) tell someone to perform an action and can be punctuated with a period or an exclamation point based on the speaker's tone.","example":"Please close the door. (mild command); Close the door immediately! (strong command)","strategyClue":"Think about the purpose of each sentence type: Does it ask for information, state a fact, or give an order? Identify which one allows for variation in emphasis.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: command. A command (imperative sentence) tells someone to do something. Depending on how strongly you want to say it, you can use a period for a mild command or an exclamation point for a strong or urgent one.","incorrect":["",{"choice":"question","category":"interrogative sentence type","reason":"Questions (interrogative sentences) always end with a question mark because they are asking for information, never a period or exclamation point."},{"choice":"statement only","category":"declarative sentence type","reason":"Statements (declarative sentences) state facts or opinions and almost always end with a period. They do not change their punctuation based on the force of the words."},{"choice":"fragment","category":"incomplete sentence structure","reason":"A fragment is an incomplete thought that lacks a subject or a verb. It is not a complete sentence type, so it does not follow the rules for standard sentence ending punctuation."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"extended-context","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":21,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0022","version":5,"contentHash":"sha256:0e311e2951adf6aee7db93a3e6d80b2d96f8d32cfe7277d2851664487eeef61a","question":"Which choice changes \"Oh, no\" into a complete exclamation?","choices":["Oh, no.","Oh, no!","Oh, no?","Oh no,"],"correct":1,"studyAid":{"definition":"An exclamation point (!) is used at the end of a sentence or phrase to show strong feelings like excitement, fear, or surprise.","example":"Watch out! I am so happy! That was amazing!","strategyClue":"Read the phrase aloud with feeling. Ask yourself if the words show a strong reaction; if they do, choose the punctuation mark that signals intensity.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: Oh, no!. An exclamation point is used to show strong emotion or surprise, which is exactly what 'Oh, no' expresses.","incorrect":[{"choice":"Oh, no.","category":"incorrect end punctuation","reason":"A period is used for statements, not expressions of strong feeling. The period makes the phrase sound flat rather than urgent."},"",{"choice":"Oh, no?","category":"incorrect end punctuation","reason":"A question mark is only for asking questions. Using one here makes it sound like you are unsure if you are saying 'Oh, no'."},{"choice":"Oh no,","category":"missing end punctuation","reason":"A comma cannot end a sentence because it is used to pause within one. You need a terminal mark like an exclamation point to finish the thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":22,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0023","version":4,"contentHash":"sha256:aa8047f8bfcbd8cdc3e695ad2844fab0f63da76f789c59155ed014b1d571c060","question":"Which sentence is declarative because it gives information?","choices":["My house is near the school.","Is my house near the school?","Find my house near the school.","What a nice house near the school!"],"correct":0,"studyAid":{"definition":"A declarative sentence states a fact or an idea and ends with a period. It is the most common type of sentence used to share information.","example":"Declarative: The sky is blue. / Not declarative: Is the sky blue? (Interrogative) / Look at the blue sky! (Imperative)","strategyClue":"Look at the punctuation at the end of the sentence and ask yourself if the speaker is trying to provide a fact, ask for something, give an order, or express surprise.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: My house is near the school. A declarative sentence makes a statement or expresses an opinion and always ends with a period. This sentence provides a fact about the location of the house.","incorrect":["",{"choice":"Is my house near the school?","category":"interrogative sentence type","reason":"This is an interrogative sentence because it asks a question. It ends with a question mark and is used to gather information rather than provide it."},{"choice":"Find my house near the school.","category":"imperative sentence type","reason":"This is an imperative sentence because it gives a command or a request. The subject is implied, and it is telling someone to do an action."},{"choice":"What a nice house near the school!","category":"exclamatory sentence type","reason":"This is an exclamatory sentence because it expresses strong emotion. It ends with an exclamation point instead of a period."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"medium","4":"easy","5":"easy","6":"easy"},"primaryDifficulty":"easy","intrinsicDifficulty":"easy","cognitiveDemand":"identify-and-apply","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":35,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":23,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}},{"id":"grammar-sentence-types-q0024","version":4,"contentHash":"sha256:2fc41266af7ce914d4428bcee9a5c08b71f10e7e4d7338921b155fd2b1d7d9c2","question":"Which choice correctly explains \"Tell me what happened.\"?","choices":["It is a question because it asks for information.","It is a command because it tells someone to tell.","It is an exclamation because it has strong feeling.","It is a fragment because it has no subject."],"correct":1,"studyAid":{"definition":"An imperative sentence (command) tells someone to do something. It often starts with a verb and ends with a period, with an 'understood' subject of 'you'.","example":"Close the door. (Command) / Please help me. (Request/Command) / Do you like cake? (Question)","strategyClue":"Look at the end punctuation and the first word of the sentence. If it starts with an action verb and ends with a period, ask yourself if the speaker is giving an instruction rather than asking for a response.","link":"https://www.grammar-monster.com/","linkText":"Grammar Monster - Grammar Help"},"explanation":{"correct":"Answer: It is a command because it tells someone to tell. Imperative sentences, or commands, give instructions or requests, even if they end in a period.","incorrect":[{"choice":"It is a question because it asks for information.","category":"confusing sentence types","reason":"Although the sentence asks for information, it does not use a question mark and does not follow the structure of an interrogative sentence like 'What happened?'"},"",{"choice":"It is an exclamation because it has strong feeling.","category":"incorrect punctuation tone","reason":"Exclamations express strong emotion and end with an exclamation point. This sentence uses a period, which shows it is a standard command."},{"choice":"It is a fragment because it has no subject.","category":"hidden subject rule","reason":"Commands have a 'hidden' subject. The subject 'you' is understood to be the person being spoken to, making the sentence a complete thought."}]},"metadata":{"gradeLevels":[3,4,5,6],"difficultyByGrade":{"3":"hard","4":"medium","5":"easy","6":"easy"},"primaryDifficulty":"medium","intrinsicDifficulty":"medium","cognitiveDemand":"apply-with-context","languageDemand":"short-prompt","skills":["grammar","usage","sentence analysis"],"feedbackFocus":"name the rule, test it against each choice, and explain the deciding clue","estimatedTimeSeconds":55,"reviewPriority":"normal","sourceSet":"grammar-sentence-types","sequence":24,"skillIds":["grammar.sentence-analysis","grammar.usage"],"standardIds":["L.3-6.1"]}}],"metadata":{"gradesSupported":[3,4,5,6],"difficultiesSupported":["easy","medium","hard"],"selectorPolicy":"grade+difficulty selects exact matches first, then nearby grade-appropriate practice to fill the configured mission length"}}}
  );
})();
